head.b:skin:
:root{--bg:#fbf8f3;--paper:#fff;--ink:#1f1d1a;--muted:#6f6a62;--line:#ebe5da;--accent:#d9442b;--accent-soft:#fde9e4;--teal:#1f7a6d;--teal-soft:#e2f2ef;--gold:#f2b544}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.65 Inter,"Noto Sans JP","Noto Sans KR",system-ui,sans-serif}
a{color:inherit;text-decoration:none}
.wrap{max-width:1120px;margin:0 auto;padding:0 20px}
.sl-head{background:var(--paper);border-bottom:1px solid var(--line);position:sticky;top:0;z-index:5}
.sl-nav{display:flex;align-items:center;gap:24px;height:64px}
.sl-logo{font:700 24px Fraunces,Georgia,serif;letter-spacing:-.5px}.sl-logo span{color:var(--accent)}
.sl-menu{display:flex;gap:20px;font-weight:500;font-size:15px;color:var(--muted)}.sl-menu a:hover{color:var(--ink)}
.sl-lang{margin-left:auto;display:flex;gap:6px}
.sl-lang a{font-size:13px;padding:4px 10px;border:1px solid var(--line);border-radius:99px}
.sl-lang a.on{background:var(--ink);color:#fff;border-color:var(--ink)}
.sl-hero{padding:52px 0 28px;max-width:720px}
.eyebrow{font-size:13px;font-weight:600;letter-spacing:.12em;text-transform:uppercase;color:var(--teal)}
.sl-hero h1{font:700 46px/1.1 Fraunces,Georgia,serif;margin:10px 0 14px;letter-spacing:-1px}
.sl-hero p{color:var(--muted);font-size:18px;margin:0 0 22px}
.sl-search{display:flex;background:var(--paper);border:1px solid var(--line);border-radius:14px;padding:6px}
.sl-search input{flex:1;border:0;font:inherit;padding:10px 12px;background:transparent;outline:none}
.sl-search button{border:0;background:var(--accent);color:#fff;font-weight:600;border-radius:10px;padding:0 18px;cursor:pointer}
.sec-title{font:700 24px Fraunces,Georgia,serif;margin:8px 0 14px}
.areas{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:0 0 36px}
.area{background:var(--paper);border:1px solid var(--line);border-radius:16px;padding:14px 16px;display:flex;flex-direction:column;gap:2px}
.area b{font:600 17px Fraunces,Georgia,serif}.area span{font-size:13px;color:var(--muted)}
.area:hover{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-soft)}
.layout{display:grid;grid-template-columns:1fr 300px;gap:32px;padding:20px 0 64px}
.cards{display:grid;grid-template-columns:repeat(2,1fr);gap:22px}
.card{background:var(--paper);border:1px solid var(--line);border-radius:18px;overflow:hidden;display:flex;flex-direction:column}
.card .img{aspect-ratio:16/10;background:#eee;overflow:hidden}.card .img img{width:100%;height:100%;object-fit:cover;display:block}
.card .body{padding:16px 18px 18px;display:flex;flex-direction:column;gap:8px;flex:1}
.meta{font-size:13px;color:var(--muted)}
.card h3{font:600 20px/1.28 Fraunces,Georgia,serif;margin:0}
.card p{margin:0;color:var(--muted);font-size:15px}
.card .more{margin-top:auto;font-size:14px;font-weight:600;color:var(--teal)}
.pager{display:flex;justify-content:space-between;margin:28px 0 0;font-weight:600;color:var(--teal)}
.empty{background:var(--paper);border:1px dashed var(--line);border-radius:18px;padding:40px;text-align:center;color:var(--muted)}
aside .box{background:var(--paper);border:1px solid var(--line);border-radius:18px;padding:20px;margin-bottom:20px}
aside h4{font:700 18px Fraunces,Georgia,serif;margin:0 0 8px}
.about{display:flex;gap:12px;align-items:center;margin-bottom:10px}
.avatar{width:52px;height:52px;border-radius:50%;background:var(--gold);display:grid;place-items:center;font:700 22px Fraunces,Georgia,serif;color:#fff;flex:none}
.legend div{font-size:14px;margin:6px 0}
.fxnote{font-size:13px;color:var(--muted)}
.post-wrap{max-width:780px}
.post-title{font:700 38px/1.15 Fraunces,Georgia,serif;margin:6px 0 12px;letter-spacing:-.6px}
.byline{display:flex;align-items:center;gap:10px;font-size:14px;color:var(--muted);margin-bottom:20px}
.byline .avatar{width:34px;height:34px;font-size:15px}
.post-labels{margin:30px 0 0;font-size:14px;color:var(--muted)}
.post-labels a{display:inline-block;margin:4px 6px 0 0;padding:3px 10px;border-radius:99px;background:var(--teal-soft);color:var(--teal);font-weight:600}
.sl-foot{border-top:1px solid var(--line);padding:28px 0;color:var(--muted);font-size:14px}
@media (max-width:860px){.sl-hero h1{font-size:34px}.layout{grid-template-columns:1fr}.cards{grid-template-columns:1fr}.sl-menu{display:none}.areas{grid-template-columns:1fr 1fr}.post-title{font-size:30px}}
